describe('Async State Preservation During Browser Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should preserve async state when navigating forward and back', () => {
    // Load initial page and trigger async operation
    cy.get('[data-testid="load-data-btn"]').click();

    // Wait for async operation to complete
    cy.get('[data-testid="loading-spinner"]', { timeout: 10000 }).should('not.exist');

    // Verify data is loaded
    cy.get('[data-testid="data-display"]').should('contain', 'Data loaded');
    cy.get('[data-testid="async-value"]').then(($el) => {
      const initialValue = $el.text();
      expect(initialValue).to.not.be.empty;

      // Navigate to another page
      cy.get('[data-testid="navigate-link"]').click();
      cy.url().should('include', '/page2');

      // Navigate back
      cy.go('back');
      cy.url().should('include', '/');

      // Verify async state is preserved
      cy.get('[data-testid="async-value"]').should('contain', initialValue);
      cy.get('[data-testid="data-display"]').should('contain', 'Data loaded');
    });
  });

  it('should handle rapid navigation without losing async state', () => {
    // Trigger async operation
    cy.get('[data-testid="load-data-btn"]').click();
    cy.get('[data-testid="loading-spinner"]', { timeout: 10000 }).should('not.exist');

    // Store the loaded value
    cy.get('[data-testid="async-value"]').invoke('text').as('loadedValue');

    // Perform rapid navigation
    cy.get('[data-testid="navigate-link"]').click();
    cy.go('back');
    cy.go('forward');
    cy.go('back');

    // Verify state is still preserved after rapid navigation
    cy.get('@loadedValue').then((expectedValue) => {
      cy.get('[data-testid="async-value"]').should('contain', expectedValue);
    });

    // Verify no loading spinner appears (state was cached)
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should preserve multiple async states during navigation', () => {
    // Load first async data
    cy.get('[data-testid="load-user-btn"]').click();
    cy.get('[data-testid="user-loading"]', { timeout: 10000 }).should('not.exist');
    cy.get('[data-testid="user-name"]').invoke('text').as('userName');

    // Load second async data
    cy.get('[data-testid="load-posts-btn"]').click();
    cy.get('[data-testid="posts-loading"]', { timeout: 10000 }).should('not.exist');
    cy.get('[data-testid="posts-count"]').invoke('text').as('postsCount');

    // Navigate away and back
    cy.get('[data-testid="navigate-link"]').click();
    cy.go('back');

    // Verify both async states are preserved
    cy.get('@userName').then((userName) => {
      cy.get('[data-testid="user-name"]').should('contain', userName);
    });

    cy.get('@postsCount').then((postsCount) => {
      cy.get('[data-testid="posts-count"]').should('contain', postsCount);
    });
  });

  it('should handle async state when page refresh occurs', () => {
    // Load async data
    cy.get('[data-testid="load-data-btn"]').click();
    cy.get('[data-testid="loading-spinner"]', { timeout: 10000 }).should('not.exist');
    cy.get('[data-testid="data-display"]').should('contain', 'Data loaded');

    // Refresh page
    cy.reload();

    // After refresh, async operation should be triggered again
    cy.get('[data-testid="loading-spinner"]', { timeout: 10000 }).should('not.exist');
    cy.get('[data-testid="data-display"]').should('contain', 'Data loaded');
  });
});
